<script>
/* Liens utiles — carrousel partenaires + filtres du répertoire.
   Autonome (aucune dépendance), scopé, respecte prefers-reduced-motion. */
(function () {
  'use strict';

  /* ----- Carrousel ----- */
  var ads = document.querySelector('.ba-ads');
  if (ads) {
    var track = ads.querySelector('.ba-ads__track');
    var slides = track ? Array.prototype.slice.call(track.children) : [];
    var dotsWrap = ads.querySelector('.ba-ads__dots');
    if (slides.length > 1) {
      var i = 0, timer = null, paused = false;
      var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      slides.forEach(function (_, n) {
        var d = document.createElement('button');
        d.className = 'ba-ads__dot';
        d.type = 'button';
        d.setAttribute('role', 'tab');
        d.setAttribute('aria-label', 'Annonce ' + (n + 1));
        d.addEventListener('click', function () { go(n); restart(); });
        dotsWrap.appendChild(d);
      });
      var dots = Array.prototype.slice.call(dotsWrap.children);

      function go(n) {
        i = (n + slides.length) % slides.length;
        track.style.transform = 'translateX(' + (-i * 100) + '%)';
        dots.forEach(function (d, k) { d.setAttribute('aria-selected', k === i ? 'true' : 'false'); });
      }
      function next() { go(i + 1); }
      function start() { if (reduce || paused) return; timer = setInterval(next, 6000); }
      function stop() { if (timer) { clearInterval(timer); timer = null; } }
      function restart() { stop(); start(); }

      var prev = ads.querySelector('.ba-ads__nav--prev');
      var nxt = ads.querySelector('.ba-ads__nav--next');
      if (prev) prev.addEventListener('click', function () { go(i - 1); restart(); });
      if (nxt) nxt.addEventListener('click', function () { go(i + 1); restart(); });

      ['mouseenter', 'focusin'].forEach(function (e) { ads.addEventListener(e, function () { paused = true; stop(); }); });
      ['mouseleave', 'focusout'].forEach(function (e) { ads.addEventListener(e, function () { paused = false; start(); }); });
      document.addEventListener('visibilitychange', function () { document.hidden ? stop() : start(); });

      go(0); start();
    }
  }

  /* ----- Répertoire : recherche, filtres, « voir plus » ----- */
  var grid = document.getElementById('ba-grid');
  if (!grid) return;
  var cards = Array.prototype.slice.call(grid.querySelectorAll('.ba-dir__card'));
  var q = document.getElementById('ba-q');
  var fCat = document.getElementById('ba-cat');
  var fCom = document.getElementById('ba-com');
  var fTyp = document.getElementById('ba-typ');
  var reset = document.getElementById('ba-reset');
  var countEl = document.getElementById('ba-count');
  var empty = document.getElementById('ba-empty');
  var moreBtn = document.getElementById('ba-more');
  var emptyReset = document.getElementById('ba-empty-reset');
  var STEP = 12, shown = STEP;

  function norm(s) {
    return (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  }
  function apply(resetShown) {
    if (resetShown) shown = STEP;
    var term = norm(q.value.trim());
    var cat = fCat.value, com = fCom.value, typ = fTyp.value;
    var matches = cards.filter(function (c) {
      if (cat && c.dataset.cat !== cat) return false;
      if (com && c.dataset.commune !== com) return false;
      if (typ && c.dataset.type !== typ) return false;
      if (term && norm(c.dataset.search).indexOf(term) === -1) return false;
      return true;
    });
    cards.forEach(function (c) { c.classList.add('is-hidden'); });
    matches.slice(0, shown).forEach(function (c) { c.classList.remove('is-hidden'); });
    countEl.textContent = matches.length;
    empty.hidden = matches.length !== 0;
    moreBtn.hidden = matches.length <= shown;
    grid.hidden = matches.length === 0;
  }
  [q, fCat, fCom, fTyp].forEach(function (el) {
    if (!el) return;
    el.addEventListener('input', function () { apply(true); });
    el.addEventListener('change', function () { apply(true); });
  });
  function clearAll() { q.value = ''; fCat.value = ''; fCom.value = ''; fTyp.value = ''; apply(true); }
  if (reset) reset.addEventListener('click', clearAll);
  if (emptyReset) emptyReset.addEventListener('click', clearAll);
  if (moreBtn) moreBtn.addEventListener('click', function () { shown += STEP; apply(false); });

  apply(true);
})();

</script>
